function healthIntelModel() {
  if (process.env.ROBOTDOJO_HEALTH_INTEL_MODEL) return process.env.ROBOTDOJO_HEALTH_INTEL_MODEL;
  return modelFor('best');
}
const HEALTH_INTEL_TIMEOUT_MS = Number.isFinite(Number(process.env.ROBOTDOJO_HEALTH_INTEL_TIMEOUT_MS))
  && Number(process.env.ROBOTDOJO_HEALTH_INTEL_TIMEOUT_MS) > 0
  ? Number(process.env.ROBOTDOJO_HEALTH_INTEL_TIMEOUT_MS)
  : 300_000;
