export const TABS = ['insights'];
export const LEGACY_TABS = ['intel', 'diet', 'rx', 'nextvisit', 'chronology'];

export function resolveIntelTab(tab) {
  if (TABS.includes(tab)) return tab;
  if (LEGACY_TABS.includes(tab) || tab === 'all') return 'insights';
  return null;
}

// ─── UI config loader ─────────────────────────────────────────────────────

const HEALTH_UI_CONFIG_PATH = resolve(__dirname, '..', 'config', 'health-ui.json');
let _uiConfig = null;
let _uiConfigMtimeMs = null;
export function getUIConfig() {
  try {
    const mtimeMs = statSync(HEALTH_UI_CONFIG_PATH).mtimeMs;
    if (_uiConfig && _uiConfigMtimeMs === mtimeMs) return _uiConfig;
    _uiConfig = JSON.parse(readFileSync(HEALTH_UI_CONFIG_PATH, 'utf-8'));
    _uiConfigMtimeMs = mtimeMs;
  } catch (err) {
    console.warn('[health-intel] health-ui.json unavailable:', err.message);
    _uiConfig = { conditionGroups: [], rxGroups: [], bodyAreaMap: {}, rxMarkerMap: {} };
    _uiConfigMtimeMs = null;
  }
  return _uiConfig;
}

let _foodOntology = null;
const HEALTH_FOOD_ONTOLOGY_PATH = resolve(__dirname, '..', 'config', 'health-food-ontology.json');
export function getFoodOntology() {
  if (_foodOntology) return _foodOntology;
  try {
    _foodOntology = JSON.parse(readFileSync(HEALTH_FOOD_ONTOLOGY_PATH, 'utf-8'));
  } catch (err) {
    console.warn('[health-intel] health-food-ontology.json unavailable:', err.message);
    _foodOntology = null;
  }
  return _foodOntology;
}

function healthFoodOntologyUpdatedAt() {
  try {
    return statSync(HEALTH_FOOD_ONTOLOGY_PATH).mtime.toISOString();
  } catch {
    return null;
  }
}

function stableForSignature(value) {
  if (Array.isArray(value)) return value.map(stableForSignature);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.keys(value)
      .filter(key => key !== 'color')
      .sort()
      .map(key => [key, stableForSignature(value[key])])
  );
}

function hashSignature(value) {
  return createHash('sha256')
    .update(JSON.stringify(stableForSignature(value)))
    .digest('hex');
}

export function healthIntelSemanticUiConfig(ui = getUIConfig()) {
  return stableForSignature({
    conditionGroups: ui?.conditionGroups || [],
    rxGroups: ui?.rxGroups || [],
    bodyAreaMap: ui?.bodyAreaMap || {},
    rxMarkerMap: ui?.rxMarkerMap || {},
    definitions: ui?.definitions || {},
  });
}

function healthIntelInputSnapshot() {
  const latest = {
    dataPoints: latestTimestamp('health_data_points', 'created_at'),
    imports: latestTimestamp('health_ingestion_log', 'created_at', 'COALESCE(record_count, 0) > 0'),
    markers: latestTimestamp('health_markers', 'updated_at'),
    notes: latestTimestamp('health_notes', 'created_at'),
    curatedMedications: latestTimestamp('curated_medications', 'updated_at'),
    materialHealthContext: latestMaterialHealthTopicContextUpdatedAt(),
  };
  const latestInputAt = [
    ...Object.values(latest),
    healthFoodOntologyUpdatedAt(),
    HEALTH_INTEL_CONTEXT_UPDATED_AT,
  ].filter(Boolean).sort((a, b) => (dbDateMs(b) || 0) - (dbDateMs(a) || 0))[0] || null;

  return {
    version: 1,
    contextUpdatedAt: HEALTH_INTEL_CONTEXT_UPDATED_AT,
    latest,
    latestInputAt,
    healthUi: healthIntelSemanticUiConfig(),
    foodOntology: getFoodOntology() || null,
  };
}

export function healthIntelInputSignature(tab = 'all', snapshot = healthIntelInputSnapshot()) {
  return hashSignature({
    version: snapshot.version,
    tab,
    contextUpdatedAt: snapshot.contextUpdatedAt,
    latest: snapshot.latest,
    healthUi: snapshot.healthUi,
    foodOntology: snapshot.foodOntology,
  });
}

// ─── Cache API (prepared lazily so callers can import without a DB roundtrip) ─

let _stmts = null;
function stmts() {
  if (_stmts) return _stmts;
  _stmts = {
    getIntel: db.prepare(`
      SELECT tab, content, generated_at, model, input_tokens, output_tokens, input_signature
      FROM health_intel WHERE tab = ?
    `),
    upsertIntel: db.prepare(`
      INSERT INTO health_intel (tab, content, generated_at, model, input_tokens, output_tokens, input_signature)
      VALUES (?, ?, datetime('now'), ?, ?, ?, ?)
      ON CONFLICT(tab) DO UPDATE SET
        content = excluded.content,
        generated_at = excluded.generated_at,
        model = excluded.model,
        input_tokens = excluded.input_tokens,
        output_tokens = excluded.output_tokens,
        input_signature = excluded.input_signature
    `),
    listIntel: db.prepare(`
      SELECT tab, content, generated_at, model, input_tokens, output_tokens, input_signature
      FROM health_intel ORDER BY tab
    `),
    backfillInputSignature: db.prepare(`
      UPDATE health_intel
      SET input_signature = ?
      WHERE tab = ?
        AND COALESCE(input_signature, '') = ''
    `),
    // Health data — robotdojo schema
    allMarkers: db.prepare(`
      SELECT id, name, unit, group_id, ref_low, ref_high, target, trend, description, auto_created
      FROM health_markers ORDER BY group_id, name
    `),
    hasAnyDataPoint: db.prepare(`
      SELECT 1 AS n
      FROM health_data_points
      WHERE excluded = 0
      LIMIT 1
    `),
    activeMeds: db.prepare(`
      SELECT name, type, dose, frequency, timing, date_started, notes
      FROM curated_medications WHERE status = 'active'
      ORDER BY type, timing, name
    `),
    allMeds: db.prepare(`
      SELECT name, type, dose, frequency, timing, date_started, date_stopped, status, notes
      FROM curated_medications ORDER BY status, type, name
    `),
  };
  return _stmts;
}

function maybeBackfillIntelInputSignature(row, freshness) {
  if (!row || row.input_signature || freshness.stale || !freshness.current_input_signature) return row;
  try {
    stmts().backfillInputSignature.run(freshness.current_input_signature, row.tab);
    row.input_signature = freshness.current_input_signature;
  } catch (err) {
    console.warn('[health-intel] could not backfill input signature:', err.message);
  }
  return row;
}

export function getIntelContent(tab, { includeStale = false } = {}) {
  const row = stmts().getIntel.get(tab) || null;
  if (!row) return null;
  const content = normalizeIntelGeneratedContent(tab, row.content);
  const inputSnapshot = healthIntelInputSnapshot();
  const freshness = intelContentFreshnessReport(tab, content, {
    generatedAt: row.generated_at,
    outputTokens: row.output_tokens,
    inputSignature: row.input_signature,
    inputSnapshot,
  });
  const stale = freshness.stale;
  maybeBackfillIntelInputSignature(row, freshness);
  if (stale && !includeStale) return null;
  return { ...row, content, stale, freshness, stale_reasons: freshness.stale_reasons };
}

export function listIntel() {
  const inputSnapshot = healthIntelInputSnapshot();
  return stmts().listIntel.all().map(({ content, ...row }) => {
    const normalized = normalizeIntelGeneratedContent(row.tab, content);
    const freshness = intelContentFreshnessReport(row.tab, normalized, {
      generatedAt: row.generated_at,
      outputTokens: row.output_tokens,
      inputSignature: row.input_signature,
      inputSnapshot,
    });
    maybeBackfillIntelInputSignature(row, freshness);
    return {
      ...row,
      content_chars: String(normalized || '').length,
      stale: freshness.stale,
      stale_reasons: freshness.stale_reasons,
      latest_input_at: freshness.latest_input_at,
    };
  });
}

export function getIntelCacheStatus(tab) {
  const inputSnapshot = healthIntelInputSnapshot();
  const row = stmts().getIntel.get(tab) || null;
  if (!row) {
    const latestInputAt = latestHealthIntelInputUpdatedAt(inputSnapshot);
    return { tab, exists: false, stale: false, generated_at: null, model: null, latest_input_at: latestInputAt, stale_reasons: [] };
  }
  const content = normalizeIntelGeneratedContent(tab, row.content);
  const freshness = intelContentFreshnessReport(tab, content, {
    generatedAt: row.generated_at,
    outputTokens: row.output_tokens,
    inputSignature: row.input_signature,
    inputSnapshot,
  });
  maybeBackfillIntelInputSignature(row, freshness);
  return {
    tab: row.tab,
    exists: true,
    stale: freshness.stale,
    stale_reasons: freshness.stale_reasons,
    missing_requirements: freshness.missing_requirements,
    latest_input_at: freshness.latest_input_at,
    current_input_signature: freshness.current_input_signature,
    input_signature: row.input_signature || '',
    input_stale: freshness.input_stale,
    signature_stale: freshness.signature_stale,
    generated_at: row.generated_at,
    model: row.model,
    input_tokens: row.input_tokens,
    output_tokens: row.output_tokens,
    content_chars: String(content || '').length,
  };
}

function saveIntelContent(tab, content, model, usage) {
  stmts().upsertIntel.run(
    tab, content, model,
    usage?.input_tokens || 0,
    usage?.output_tokens || 0,
    healthIntelInputSignature(tab),
  );
}

function maxOutputTokensForTab(tab) {
  return MAX_OUTPUT_TOKENS[tab] || 2000;
}

